{
  "justification": "Europe dominated salience (63%), indicating strong group-boundary and sovereignty/authority concerns, while mean positions are centrist economically (redistribution 4.62) but notably more authoritarian socially (6.37) and slightly pro-integration (EU 5.69). Health and environment salience add care/purity pull, with crime and economic items keeping proportionality considerations active.",
  "foundations": [
    {
      "foundation": "authority",
      "basis": "High score on the authority-liberty scale (6.37), plus salience for crime (2.8%)/terrorism (0.5%) and sovereignty themes within Europe (63%).",
      "weight": 0.24
    },
    {
      "foundation": "loyalty",
      "basis": "Europe salience 63% and items on immigration (3.4%), defence (0.1%), terrorism (0.5%) highlight in-group/out-group stakes; mean EU stance 5.69 suggests broader-coalition loyalty.",
      "weight": 0.22
    },
    {
      "foundation": "equality",
      "basis": "Redistribution self-placement 4.62 (tilt to redistribution) and salience of health (5.5%), poverty (1.2%), and inequality (1.0%).",
      "weight": 0.17
    },
    {
      "foundation": "care",
      "basis": "Health (5.5%), environment (6.6%), poverty (1.2%), inequality (1.0%), and social care (0.2%) signal harm/care priorities.",
      "weight": 0.15
    },
    {
      "foundation": "proportionality",
      "basis": "Crime (2.8%), economy-general (2.3%), austerity (0.7%), and fairness disputes tied to Europe’s 63% salience.",
      "weight": 0.12
    },
    {
      "foundation": "sanctity",
      "basis": "Environment salience (6.6%) and a small morals category (0.2%) map onto purity/contamination and naturalness concerns.",
      "weight": 0.1
    }
  ]
}
